<?phprequire_once "db.php";if (!isset($_GET['id'])) {    die("Subject ID Missing!");}$id = (int)$_GET['id'];$message = "";// Get Subject Details$result = pg_query_params(    $conn,    "SELECT * FROM subjects WHERE subject_id = $1",    [$id]);if (!$result || pg_num_rows($result) == 0) {    die("Subject Not Found!");}$subject = pg_fetch_assoc($result);// Update Subjectif (isset($_POST['update_subject'])) {    $name = trim($_POST['subject_name']);    $code = trim($_POST['subject_code']);    $semester = (int)$_POST['semester'];    $teacher_id = !empty($_POST['teacher_id'])        ? (int)$_POST['teacher_id']        : null;    $sql = "UPDATE subjects            SET subject_name = $1,                subject_code = $2,                semester = $3,                teacher_id = $4            WHERE subject_id = $5";    $update = pg_query_params(        $conn,        $sql,        [$name, $code, $semester, $teacher_id, $id]    );    if ($update) {        header("Location: subject.php");        exit();    } else {        $message = "Error: " . pg_last_error($conn);    }}$teachers = pg_query(    $conn,    "SELECT teacher_id, teacher_name FROM teachers");?><!DOCTYPE html><html><head>    <title>Edit Subject</title>    <link rel="stylesheet" href="subject.css"></head><body><div class="subject-container">    <div class="subject-form">        <h2>Edit Subject</h2>        <p><?php echo htmlspecialchars($message); ?></p>        <form method="POST">            <input type="text"            name="subject_name"            value="<?php echo htmlspecialchars($subject['subject_name']); ?>"            placeholder="Subject Name"            required>            <input type="text"            name="subject_code"            value="<?php echo htmlspecialchars($subject['subject_code']); ?>"            placeholder="Subject Code"            required>            <input type="number"            name="semester"            value="<?php echo htmlspecialchars($subject['semester']); ?>"            min="1"            required>            <select name="teacher_id">                <option value="">Select Teacher</option>                <?php while ($teacher = pg_fetch_assoc($teachers)) { ?>                <option value="<?php echo $teacher['teacher_id']; ?>"                <?php                if ($subject['teacher_id'] == $teacher['teacher_id']) {                    echo "selected";                }                ?>>                <?php echo htmlspecialchars($teacher['teacher_name']); ?>                </option>                <?php } ?>            </select>            <button type="submit" name="update_subject">                Update Subject            </button>        </form>        <br>        <a href="subject.php">Back to Subjects</a>    </div></div></body></html>